      process.env.HTTP_LOG_SUCCESS_BODY != null
        ? process.env.HTTP_LOG_SUCCESS_BODY === 'true'
        : (process.env.NODE_ENV || 'development') === 'development',
  },
  cors: {
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'] as string[],
