  @Property({ onCreate: () => new Date(), onUpdate: () => new Date() })
  updatedAt!: Date;

  @Property({ nullable: true })
  deletedAt?: Date | null;

  @ManyToOne(() => Message, {
    nullable: true,
    deleteRule: 'cascade',
    fieldName: 'parentId',
  })
  parent?: Message | null;

  @OneToMany(() => Message, (message) => message.parent)
  replies!: Message[];

  @ManyToOne(() => User, {
    nullable: true,
    fieldName: 'receiverId',
  })
  receiver?: User | null;

  @ManyToOne(() => User, {
    nullable: true,
    fieldName: 'senderId',
  })
  sender?: User | null;

  @ManyToOne(() => Group, {
    nullable: true,
    deleteRule: 'cascade',
    fieldName: 'groupId',
  })
  group?: Group | null;

  @OneToMany(() => MessageRead, (messageRead) => messageRead.message)
  reads!: MessageRead[];
}

