import {
  toEntityId,
  toEntityIdList,
  relationEntityId,
} from '../common/entity-id';
import {
  BadRequestException,
  Injectable,
  Logger,
  NotFoundException,
} from '@nestjs/common';
import { EntityManager, type FilterQuery } from '@mikro-orm/core';
import { Event } from '../entities/event.entity';
import {
  AttendanceStatus,
  CheckinMethod,
  EventRegistration,
  RegistrationStatus,
} from '../entities/event-registration.entity';
import { SocketGateway } from '../socket/socket.gateway';
import type { EventAttendanceSocketPayload } from '../socket/socket.types';
import type { EventRegistrationRowDto } from './event-registrations.service';
import { EventRegistrationsService } from './event-registrations.service';

export type AttendanceSource = 'hanet' | 'manual';

export type ManualAttendanceAction =
  | 'checkin'
  | 'checkout'
  | 'reset-checkin'
  | 'reset-checkout'
  | 'reset-all';

export type ApplyAttendanceResult = {
  kind: 'checkin' | 'checkout';
  eventId: number;
  email: string;
  fullName: string;
  registrationId: number;
  at: string;
  duplicate?: boolean;
  registration: EventRegistrationRowDto;
};

@Injectable()
export class EventRegistrationAttendanceService {
  private readonly logger = new Logger(EventRegistrationAttendanceService.name);

  constructor(
    private readonly em: EntityManager,
    private readonly socketGateway: SocketGateway,
    private readonly eventRegistrationsService: EventRegistrationsService,
  ) {}

  async applyManual(
    registrationId: string,
    action: ManualAttendanceAction,
  ): Promise<EventRegistrationRowDto> {
    const reg = await this.em.findOne(EventRegistration, {
      id: toEntityId(registrationId),
      deletedAt: null,
    });
    if (!reg) {
      throw new NotFoundException('Không tìm thấy đăng ký sự kiện');
    }

    const eventId = relationEntityId(reg.event);
    if (eventId == null) {
      throw new BadRequestException('Đăng ký không gắn sự kiện hợp lệ');
    }

    const at = new Date();

    switch (action) {
      case 'checkin': {
        await this.recordCheckin({
          eventId,
          registration: reg,
          at,
          source: 'manual',
          skipWindowCheck: true,
        });
        break;
      }
      case 'checkout': {
        await this.recordCheckout({
          eventId,
          registration: reg,
          at,
          source: 'manual',
          skipWindowCheck: true,
        });
        break;
      }
      case 'reset-checkin':
        reg.hasCheckin = false;
        reg.checkinMethod = CheckinMethod.NONE;
        if (reg.hasCheckout) {
          reg.hasCheckout = false;
        }
        reg.attendanceStatus = AttendanceStatus.NOT_ATTENDED;
        reg.updatedAt = at;
        await this.em.flush();
        await this.syncEventCounts(eventId);
        this.emitState(reg, eventId, 'checkin', 'manual', { duplicate: false });
        break;
      case 'reset-checkout':
        reg.hasCheckout = false;
        reg.attendanceStatus = reg.hasCheckin
          ? AttendanceStatus.PARTIAL
          : AttendanceStatus.NOT_ATTENDED;
        reg.updatedAt = at;
        await this.em.flush();
        await this.syncEventCounts(eventId);
        this.emitState(reg, eventId, 'checkout', 'manual', {
          duplicate: false,
        });
        break;
      case 'reset-all':
        reg.hasCheckin = false;
        reg.hasCheckout = false;
        reg.checkinMethod = CheckinMethod.NONE;
        reg.attendanceStatus = AttendanceStatus.NOT_ATTENDED;
        reg.updatedAt = at;
        await this.em.flush();
        await this.syncEventCounts(eventId);
        this.emitState(reg, eventId, 'checkin', 'manual', { duplicate: false });
        break;
      default:
        throw new BadRequestException('Thao tác attendance không hợp lệ');
    }

    const row = await this.eventRegistrationsService.getById(registrationId);
    if (!row) {
      throw new NotFoundException('Không tìm thấy đăng ký sự kiện');
    }
    return row;
  }

  async recordCheckin(input: {
    eventId: number;
    registration: EventRegistration;
    at: Date;
    source: AttendanceSource;
    deviceId?: string | null;
    deviceName?: string | null;
    skipWindowCheck?: boolean;
  }): Promise<ApplyAttendanceResult> {
    const { eventId, registration: reg, at, source } = input;
    if (!input.skipWindowCheck) {
      const event = await this.loadEvent(eventId);
      this.assertEventAllows(event, 'checkin', at);
    }

    if (reg.hasCheckin) {
      this.logger.debug(
        `Attendance check-in bỏ qua (đã check-in) event=${eventId} email=${reg.email}`,
      );
      const result = await this.toResult(eventId, reg, 'checkin', true);
      this.emitState(reg, eventId, 'checkin', source, {
        duplicate: true,
        deviceId: input.deviceId,
        deviceName: input.deviceName,
      });
      return result;
    }

    reg.hasCheckin = true;
    reg.faceVerified = source === 'hanet' ? true : reg.faceVerified;
    reg.checkinMethod =
      source === 'manual' ? CheckinMethod.MANUAL : CheckinMethod.FACE_ID;
    reg.updatedAt = at;
    if (reg.status === RegistrationStatus.PENDING) {
      reg.status = RegistrationStatus.CONFIRMED;
    }
    if (reg.attendanceStatus === AttendanceStatus.NOT_ATTENDED) {
      reg.attendanceStatus = AttendanceStatus.PARTIAL;
    }
    await this.em.flush();
    await this.syncEventCounts(eventId);

    const result = await this.toResult(eventId, reg, 'checkin', false);
    this.emitState(reg, eventId, 'checkin', source, {
      duplicate: false,
      deviceId: input.deviceId,
      deviceName: input.deviceName,
    });
    this.logger.log(
      `Attendance check-in (${source}) event=${eventId} email=${reg.email}`,
    );
    return result;
  }

  async recordCheckout(input: {
    eventId: number;
    registration: EventRegistration;
    at: Date;
    source: AttendanceSource;
    skipWindowCheck?: boolean;
  }): Promise<ApplyAttendanceResult> {
    const { eventId, registration: reg, at, source } = input;
    if (!input.skipWindowCheck) {
      const event = await this.loadEvent(eventId);
      this.assertEventAllows(event, 'checkout', at);
    }

    if (reg.hasCheckout) {
      this.logger.debug(
        `Attendance check-out bỏ qua (đã check-out) event=${eventId} email=${reg.email}`,
      );
      const result = await this.toResult(eventId, reg, 'checkout', true);
      this.emitState(reg, eventId, 'checkout', source, { duplicate: true });
      return result;
    }

    if (!reg.hasCheckin) {
      reg.hasCheckin = true;
      if (reg.attendanceStatus === AttendanceStatus.NOT_ATTENDED) {
        reg.attendanceStatus = AttendanceStatus.PARTIAL;
      }
    }

    reg.hasCheckout = true;
    reg.faceVerified = source === 'hanet' ? true : reg.faceVerified;
    reg.attendanceStatus = AttendanceStatus.FULL;
    reg.updatedAt = at;
    await this.em.flush();
    await this.syncEventCounts(eventId);

    const result = await this.toResult(eventId, reg, 'checkout', false);
    this.emitState(reg, eventId, 'checkout', source, { duplicate: false });
    this.logger.log(
      `Attendance check-out (${source}) event=${eventId} email=${reg.email}`,
    );
    return result;
  }

  private async loadEvent(eventId: number): Promise<Event> {
    const event = await this.em.findOne(Event, {
      id: eventId,
      deletedAt: null,
    });
    if (!event) {
      throw new NotFoundException('Không tìm thấy sự kiện');
    }
    return event;
  }

  private assertEventAllows(
    event: Event,
    kind: 'checkin' | 'checkout',
    at: Date,
  ): void {
    if (kind === 'checkin' && !event.allowCheckin) {
      throw new BadRequestException('Sự kiện không cho phép check-in');
    }
    if (kind === 'checkout' && !event.allowCheckout) {
      throw new BadRequestException('Sự kiện không cho phép check-out');
    }

    const within = (start?: Date | null, end?: Date | null) => {
      if (start && at < start) return false;
      if (end && at > end) return false;
      return true;
    };

    if (kind === 'checkin') {
      if (
        (event.checkinStart || event.checkinEnd) &&
        !within(event.checkinStart, event.checkinEnd)
      ) {
        throw new BadRequestException(
          'Thời điểm check-in nằm ngoài khung giờ cho phép',
        );
      }
      return;
    }

    const windowStart = event.checkoutStart ?? event.checkinEnd ?? null;
    const windowEnd = event.checkoutEnd ?? event.endDate ?? null;
    if ((windowStart || windowEnd) && !within(windowStart, windowEnd)) {
      throw new BadRequestException(
        'Thời điểm check-out nằm ngoài khung giờ cho phép',
      );
    }
  }

  private async syncEventCounts(eventId: number): Promise<void> {
    const checkinCount = await this.em.count(EventRegistration, {
      event: eventId,
      hasCheckin: true,
      deletedAt: null,
    } as FilterQuery<EventRegistration>);
    const checkoutCount = await this.em.count(EventRegistration, {
      event: eventId,
      hasCheckout: true,
      deletedAt: null,
    } as FilterQuery<EventRegistration>);
    await this.em.nativeUpdate(
      Event,
      { id: eventId },
      { totalCheckins: checkinCount, totalCheckouts: checkoutCount },
    );
  }

  private async toResult(
    eventId: number,
    reg: EventRegistration,
    kind: 'checkin' | 'checkout',
    duplicate: boolean,
  ): Promise<ApplyAttendanceResult> {
    const mapped = await this.eventRegistrationsService.getById(String(reg.id));
    if (!mapped) {
      throw new NotFoundException('Không tìm thấy đăng ký sự kiện');
    }
    return {
      kind,
      eventId,
      email: reg.email,
      fullName: reg.fullName,
      registrationId: reg.id,
      at: reg.updatedAt.toISOString(),
      duplicate,
      registration: mapped,
    };
  }

  private emitState(
    reg: EventRegistration,
    eventId: number,
    kind: 'checkin' | 'checkout',
    source: AttendanceSource,
    extra: {
      duplicate?: boolean;
      deviceId?: string | null;
      deviceName?: string | null;
    },
  ): void {
    const payload: EventAttendanceSocketPayload = {
      kind,
      eventId,
      at: reg.updatedAt.toISOString(),
      email: reg.email,
      fullName: reg.fullName,
      source,
      deviceId: extra.deviceId ?? null,
      deviceName: extra.deviceName ?? null,
      registrationId: reg.id,
      checkinId: null,
      duplicate: extra.duplicate,
      hasCheckin: reg.hasCheckin,
      hasCheckout: reg.hasCheckout,
    };
    this.socketGateway.emitEventAttendance(payload);
  }
}

import {
  ApiTags,
  ApiOperation,
  ApiHeader,
  ApiBody,
  ApiResponse,
} from '@nestjs/swagger';
import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Body,
  Param,
  Query,
  Headers,
  Res,
  Logger,
} from '@nestjs/common';
import type { Response } from 'express';
import {
  EventRegistrationAttendanceService,
  type ManualAttendanceAction,
} from './event-registration-attendance.service';
import { EventRegistrationsService } from './event-registrations.service';
import {
  createSuccessResponse,
  createErrorResponse,
} from '../common/api-response';
import { Permissions } from '../common/permissions.decorator';
import { PERMISSIONS } from '../config/permissions';
import { APP_HEADERS, ADMIN_ROUTES } from '../config/constants';
import { isBulkAction, type BulkAction } from '../common/bulk-actions';
import { parseAdminListLimit } from '../common/parse-list-query';

@ApiTags('Event Registrations')
@Permissions(PERMISSIONS.EVENT_REGISTRATIONS_VIEW)
@Controller(ADMIN_ROUTES.EVENT_REGISTRATIONS)
export class EventRegistrationsController {
  private readonly logger = new Logger(EventRegistrationsController.name);

  constructor(
    private readonly eventRegistrationsService: EventRegistrationsService,
    private readonly attendanceService: EventRegistrationAttendanceService,
  ) {}

  private getUserId(
    headers: Record<string, string | undefined>,
  ): string | null {
    const id = headers[APP_HEADERS.USER_ID]?.trim();
    return id || null;
  }

  private unauthorized(res: Response): Response {
    const { statusCode, body } = createErrorResponse('Thiếu header X-User-Id', {
      status: 401,
    });
    return res.status(statusCode).json(body);
  }

  @Get()
  @ApiOperation({ summary: 'List event registrations with pagination' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async list(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Query('eventId') eventId?: string,
    @Query('page') page?: string,
    @Query('limit') limit?: string,
    @Query('search') search?: string,
    @Query('status') status?: string,
  ) {
    this.logger.log(
      `list eventId=${eventId} page=${page ?? 1} limit=${limit ?? 10}`,
    );
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    if (!eventId?.trim()) {
      const { statusCode, body } = createErrorResponse('eventId là bắt buộc', {
        status: 400,
      });
      return res.status(statusCode).json(body);
    }
    const trimmedEventId = eventId.trim();
    await this.eventRegistrationsService.syncEventRegistrationCount(
      trimmedEventId,
    );
    const result = await this.eventRegistrationsService.list({
      eventId: trimmedEventId,
      page: Math.max(1, parseInt(String(page), 10) || 1),
      limit: parseAdminListLimit(limit, 10),
      search: search?.trim(),
      status: status?.trim(),
    });
    const { statusCode, body } = createSuccessResponse({
      data: result.data,
      pagination: result.pagination,
    });
    return res.status(statusCode).json(body);
  }

  @Get(':id')
  @ApiOperation({ summary: 'Get event registration by ID' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async getById(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const row = await this.eventRegistrationsService.getById(id);
    if (!row) {
      const { statusCode, body } = createErrorResponse(
        'Không tìm thấy đăng ký sự kiện',
        { status: 404 },
      );
      return res.status(statusCode).json(body);
    }
    const { statusCode, body } = createSuccessResponse(row);
    return res.status(statusCode).json(body);
  }

  @Post()
  @Permissions(PERMISSIONS.EVENT_REGISTRATIONS_CREATE)
  @ApiOperation({ summary: 'Create new event registration' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async create(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Body()
    body: {
      eventId: string;
      email: string;
      fullName: string;
      phone?: string;
    },
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    if (!body?.eventId?.trim()) {
      const { statusCode, body: errBody } = createErrorResponse(
        'eventId là bắt buộc',
        { status: 400 },
      );
      return res.status(statusCode).json(errBody);
    }
    if (!body?.email?.trim()) {
      const { statusCode, body: errBody } = createErrorResponse(
        'email là bắt buộc',
        { status: 400 },
      );
      return res.status(statusCode).json(errBody);
    }
    if (!body?.fullName?.trim()) {
      const { statusCode, body: errBody } = createErrorResponse(
        'fullName là bắt buộc',
        { status: 400 },
      );
      return res.status(statusCode).json(errBody);
    }
    const created = await this.eventRegistrationsService.create({
      eventId: body.eventId.trim(),
      email: body.email.trim(),
      fullName: body.fullName.trim(),
      phone: body.phone?.trim() ?? null,
    });
    const { statusCode, body: okBody } = createSuccessResponse(created, {
      status: 201,
    });
    return res.status(statusCode).json(okBody);
  }

  @Post(':id/attendance')
  @Permissions(PERMISSIONS.EVENT_REGISTRATIONS_UPDATE)
  @ApiOperation({
    summary:
      'Cập nhật trạng thái check-in/out thủ công (khi socket lỗi hoặc điều chỉnh)',
  })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async setAttendance(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
    @Body() body: { action?: ManualAttendanceAction },
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const action = body?.action;
    const allowed: ManualAttendanceAction[] = [
      'checkin',
      'checkout',
      'reset-checkin',
      'reset-checkout',
      'reset-all',
    ];
    if (!action || !allowed.includes(action)) {
      const { statusCode, body: errBody } = createErrorResponse(
        'action phải là checkin | checkout | reset-checkin | reset-checkout | reset-all',
        { status: 400 },
      );
      return res.status(statusCode).json(errBody);
    }
    const updated = await this.attendanceService.applyManual(id, action);
    const { statusCode, body: okBody } = createSuccessResponse(updated);
    return res.status(statusCode).json(okBody);
  }

  @Put(':id')
  @Permissions(PERMISSIONS.EVENT_REGISTRATIONS_UPDATE)
  @ApiOperation({ summary: 'Update event registration by ID' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async update(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
    @Body()
    body: {
      email?: string;
      fullName?: string;
      phone?: string;
      status?: number;
      faceVerified?: boolean;
      attendanceStatus?: number;
      checkinMethod?: number;
    },
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const updated = await this.eventRegistrationsService.update(id, {
      email: body?.email?.trim(),
      fullName: body?.fullName?.trim(),
      phone:
        body?.phone !== undefined ? (body.phone?.trim() ?? null) : undefined,
      status: body?.status,
      faceVerified: body?.faceVerified,
      attendanceStatus: body?.attendanceStatus,
      checkinMethod: body?.checkinMethod,
    });
    if (!updated) {
      const { statusCode, body: errBody } = createErrorResponse(
        'Không tìm thấy đăng ký sự kiện',
        { status: 404 },
      );
      return res.status(statusCode).json(errBody);
    }
    const { statusCode, body: okBody } = createSuccessResponse(updated);
    return res.status(statusCode).json(okBody);
  }

  @Delete(':id/hard-delete')
  @Permissions(PERMISSIONS.EVENT_REGISTRATIONS_HARD_DELETE)
  @ApiOperation({ summary: 'Hard delete event registration permanently' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async hardDelete(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const ok = await this.eventRegistrationsService.hardDelete(id);
    if (!ok) {
      const { statusCode, body } = createErrorResponse(
        'Không tìm thấy đăng ký sự kiện',
        { status: 404 },
      );
      return res.status(statusCode).json(body);
    }
    const { statusCode, body } = createSuccessResponse(undefined, {
      message: 'Đã xóa vĩnh viễn đăng ký sự kiện',
    });
    return res.status(statusCode).json(body);
  }

  @Delete(':id')
  @Permissions(PERMISSIONS.EVENT_REGISTRATIONS_DELETE)
  @ApiOperation({ summary: 'Soft delete event registration' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async softDelete(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const ok = await this.eventRegistrationsService.softDelete(id);
    if (!ok) {
      const { statusCode, body } = createErrorResponse(
        'Đăng ký không tồn tại hoặc đã bị xóa',
        { status: 404 },
      );
      return res.status(statusCode).json(body);
    }
    const { statusCode, body } = createSuccessResponse(undefined, {
      message: 'Đã xóa đăng ký sự kiện',
    });
    return res.status(statusCode).json(body);
  }

  @Post(':id/restore')
  @Permissions(PERMISSIONS.EVENT_REGISTRATIONS_RESTORE)
  @ApiOperation({ summary: 'Restore soft-deleted event registration' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async restore(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const ok = await this.eventRegistrationsService.restore(id);
    if (!ok) {
      const { statusCode, body } = createErrorResponse(
        'Đăng ký không tồn tại hoặc chưa bị xóa',
        { status: 404 },
      );
      return res.status(statusCode).json(body);
    }
    const { statusCode, body } = createSuccessResponse(undefined, {
      message: 'Đã khôi phục đăng ký sự kiện',
    });
    return res.status(statusCode).json(body);
  }
  @Post('bulk')
  @Permissions(PERMISSIONS.EVENT_REGISTRATIONS_MANAGE)
  @ApiOperation({ summary: 'Bulk action on luot dang kys' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  @ApiBody({ description: 'Bulk action with ids' })
  @ApiResponse({ status: 200, description: 'Bulk action completed' })
  @ApiResponse({ status: 400, description: 'Invalid action' })
  async bulk(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Body() body: { action?: string; ids?: string[] },
  ) {
    const userId = this.getUserId(headers);
    if (!userId) {
      return this.unauthorized(res);
    }
    const action = body?.action;
    const ids = Array.isArray(body?.ids) ? body.ids : [];
    if (!action || !isBulkAction(action)) {
      const { statusCode, body: errBody } = createErrorResponse(
        'Action khong hop le',
        { status: 400 },
      );
      return res.status(statusCode).json(errBody);
    }
    const result = await this.eventRegistrationsService.bulk(action, ids);
    const { statusCode, body: okBody } = createSuccessResponse(
      { affected: result.affected, message: result.message },
      { message: result.message },
    );
    return res.status(statusCode).json(okBody);
  }
}

