}

function toIsoString(
  value: Date | string | number | undefined | null,
): string | null {
  if (value == null) return null;
  if (value instanceof Date)
    return Number.isNaN(value.getTime()) ? null : value.toISOString();
  if (typeof value === 'number')
    return Number.isNaN(value) ? null : new Date(value).toISOString();
  if (typeof value === 'string' && value.trim()) {
    const ms = Date.parse(value);
    return Number.isNaN(ms) ? null : new Date(ms).toISOString();
  }
  return null;
}

function avatarFromFormData(formData: unknown): string | null {
  if (formData == null || typeof formData !== 'object') return null;
  const record = formData as Record<string, unknown>;
  for (const key of ['avatar', 'avatarUrl', 'image', 'photo', 'profileImage']) {
    const value = record[key];
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (value && typeof value === 'object') {
      const nested = value as Record<string, unknown>;
      if (typeof nested.url === 'string' && nested.url.trim()) {
        return nested.url.trim();
      }
    }
  }
  return null;
}

async function loadAvatarByEmails(
  em: EntityManager,
  emails: string[],
): Promise<Map<string, string | null>> {
  const normalized = [
    ...new Set(
      emails.map((e) => e.trim().toLowerCase()).filter((e) => e.length > 0),
    ),
  ];
  const map = new Map<string, string | null>();
  if (!normalized.length) return map;

  const users = await em.find(User, {
    email: { $in: normalized },
    deletedAt: null,
  } as FilterQuery<User>);

  for (const user of users) {
    const email = user.email?.trim().toLowerCase();
    if (!email) continue;
    map.set(email, user.avatar?.trim() || null);
  }
  return map;
}

function resolveRegistrationAvatar(
  row: EventRegistration,
  avatarByEmail?: Map<string, string | null>,
): string | null {
  const fromUser = avatarByEmail?.get(row.email.trim().toLowerCase());
  if (fromUser) return fromUser;
  return avatarFromFormData(row.formData);
}

function normalizeEventIdParam(eventId: string | number): number {
  return typeof eventId === 'number' ? eventId : toEntityId(eventId);
}

function mapRow(
  r: EventRegistration,
  avatarByEmail?: Map<string, string | null>,
): EventRegistrationRowDto {
  const eventId = relationEntityId(r.event) ?? 0;
  return {
    id: r.id,
    eventId,
    email: r.email,
    fullName: r.fullName,
    avatar: resolveRegistrationAvatar(r, avatarByEmail),
    phone: r.phone ?? null,
    registeredAt: toIsoString(r.registeredAt),
    status: r.status,
    faceVerified: r.faceVerified,
    hasCheckin: r.hasCheckin,
    hasCheckout: r.hasCheckout,
    attendanceStatus: r.attendanceStatus,
    attendanceMinutes: r.attendanceMinutes,
    checkinMethod: r.checkinMethod,
    formData: r.formData,
    createdAt: toIsoString(r.createdAt),
    updatedAt: toIsoString(r.updatedAt),
    deletedAt: toIsoString(r.deletedAt),
  };
}

@Injectable()
export class EventRegistrationsService {
  constructor(private readonly em: EntityManager) {}

  /** Đếm đăng ký còn hiệu lực (không soft-delete, không hủy). */
  async countActiveForEvent(eventId: string | number): Promise<number> {
    const eid = normalizeEventIdParam(eventId);
    return this.em.count(EventRegistration, {
      event: eid,
      deletedAt: null,
      status: { $ne: RegistrationStatus.CANCELLED },
    } as FilterQuery<EventRegistration>);
  }

  /** Đồng bộ `events.totalRegistrations` với số bản ghi thực tế. */
  async syncEventRegistrationCount(eventId: string | number): Promise<number> {
    const eid = normalizeEventIdParam(eventId);
    const count = await this.countActiveForEvent(eid);
    await this.em.nativeUpdate(
      Event,
      { id: eid },
      { totalRegistrations: count },
    );
    return count;
  }

  async listPublicForEvent(
    eventId: string | number,
    limit = 100,
  ): Promise<PublicEventRegistrantDto[]> {
    const eid = normalizeEventIdParam(eventId);
    const cap = Math.min(200, Math.max(1, limit));
    const rows = await this.em.find(
      EventRegistration,
      {
        event: eid,
        deletedAt: null,
        status: { $ne: RegistrationStatus.CANCELLED },
      } as FilterQuery<EventRegistration>,
      {
        orderBy: { registeredAt: 'DESC', createdAt: 'DESC' },
        limit: cap,
        fields: ['fullName', 'registeredAt'],
      },
    );
    return rows.map((r) => ({
      fullName: r.fullName,
      registeredAt: toIsoString(r.registeredAt),
    }));
  }

  async findActiveByEventAndEmail(
    eventId: string | number,
    email: string,
  ): Promise<EventRegistrationRowDto | null> {
    const evId = normalizeEventIdParam(eventId);
    const normalizedEmail = email?.trim().toLowerCase();
    if (!normalizedEmail) return null;
    const row = await this.em.findOne(EventRegistration, {
      event: evId,
      email: normalizedEmail,
      deletedAt: null,
      status: { $ne: RegistrationStatus.CANCELLED },
    } as FilterQuery<EventRegistration>);
    if (!row) return null;
    const avatarByEmail = await loadAvatarByEmails(this.em, [row.email]);
    return mapRow(row, avatarByEmail);
  }

  async list(
    params: ListEventRegistrationsParams,
  ): Promise<ListEventRegistrationsResult> {
    const { page, limit, skip } = normalizePageLimit(
      params.page,
      params.limit,
      ADMIN_TABLE_EXPORT_MAX_LIMIT,
    );
    const where: Record<string, unknown> = {};
    where.eventId = params.eventId;
    where.deletedAt = null;
    if (params.search?.trim()) {
      const q = params.search.trim();
      where.$or = [
        { email: { $like: `%${q}%` } },
        { fullName: { $like: `%${q}%` } },
      ];
    }
    if (params.status) {
      const parsed = parseInt(params.status, 10);
      if (!Number.isNaN(parsed)) {
        where.status = parsed;
      }
    }
    const whereQuery = where as FilterQuery<EventRegistration>;
    const [rows, total] = await Promise.all([
      this.em.find(EventRegistration, whereQuery, {
        orderBy: { createdAt: 'DESC' },
        offset: skip,
        limit,
      }),
      this.em.count(EventRegistration, whereQuery),
    ]);
    const avatarByEmail = await loadAvatarByEmails(
      this.em,
      rows.map((row) => row.email),
    );
    return {
      data: rows.map((row) => mapRow(row, avatarByEmail)),
      pagination: paginationMeta(page, limit, total),
    };
  }

  async getById(id: string | number): Promise<EventRegistrationRowDto | null> {
    const r = await this.em.findOne(EventRegistration, { id: toEntityId(id) });
    if (!r) return null;
    const avatarByEmail = await loadAvatarByEmails(this.em, [r.email]);
    return mapRow(r, avatarByEmail);
  }

  async create(data: {
    eventId: string | number;
    email: string;
    fullName: string;
    phone?: string | null;
    registeredAt?: Date;
    status?: RegistrationStatus;
  }): Promise<EventRegistrationRowDto> {
    const created = new EventRegistration();
    created.event = this.em.getReference(Event, toEntityId(data.eventId));
    created.email = data.email;
    created.fullName = data.fullName;
    if (data.phone !== undefined) created.phone = data.phone;
    created.registeredAt = data.registeredAt ?? new Date();
    if (data.status !== undefined) created.status = data.status;
    await this.em.persistAndFlush(created);
    const avatarByEmail = await loadAvatarByEmails(this.em, [created.email]);
    return mapRow(created, avatarByEmail);
  }

  async update(
    id: string,
    data: {
      email?: string;
      fullName?: string;
      phone?: string | null;
      status?: RegistrationStatus;
      faceVerified?: boolean;
      attendanceStatus?: AttendanceStatus;
      checkinMethod?: CheckinMethod;
    },
  ): Promise<EventRegistrationRowDto | null> {
    const existing = await this.em.findOne(EventRegistration, {
      id: toEntityId(id),
    });
    if (!existing) return null;
    if (data.email !== undefined) existing.email = data.email;
    if (data.fullName !== undefined) existing.fullName = data.fullName;
    if (data.phone !== undefined) existing.phone = data.phone;
    if (data.status !== undefined) existing.status = data.status;
    if (data.faceVerified !== undefined)
      existing.faceVerified = data.faceVerified;
    if (data.attendanceStatus !== undefined)
      existing.attendanceStatus = data.attendanceStatus;
    if (data.checkinMethod !== undefined)
      existing.checkinMethod = data.checkinMethod;
    await this.em.persistAndFlush(existing);
    const avatarByEmail = await loadAvatarByEmails(this.em, [existing.email]);
    return mapRow(existing, avatarByEmail);
  }

  async softDelete(id: string): Promise<boolean> {
    const r = await this.em.findOne(EventRegistration, { id: toEntityId(id) });
    if (!r || r.deletedAt) return false;
    r.deletedAt = new Date();
    await this.em.persistAndFlush(r);
    return true;
  }

  async restore(id: string): Promise<boolean> {
    const r = await this.em.findOne(EventRegistration, { id: toEntityId(id) });
    if (!r || !r.deletedAt) return false;
    r.deletedAt = null;
    await this.em.persistAndFlush(r);
    return true;
  }

  async hardDelete(id: string): Promise<boolean> {
    const r = await this.em.findOne(EventRegistration, { id: toEntityId(id) });
    if (!r) return false;
    await this.em.removeAndFlush(r);
    return true;
  }
  async bulk(action: BulkAction, ids: string[]): Promise<BulkResult> {
    return applyBulkAction(this.em, EventRegistration, action, ids, {
      label: 'luot dang ky',
    });
  }
}

