import { toEntityId, toEntityIdList } from '../common/entity-id';
import { Injectable } from '@nestjs/common';
import { EntityManager, type FilterQuery } from '@mikro-orm/core';
import { Event } from '../entities/event.entity';
import { Camera } from '../entities/camera.entity';
import {
  applyBulkAction,
  type BulkAction,
  type BulkResult,
} from '../common/bulk-actions';
import { normalizePageLimit, paginationMeta } from '../common/pagination';
import { normalizePosterField } from '../common/poster-normalize';
import { ADMIN_TABLE_EXPORT_MAX_LIMIT } from '../common/pagination';
import { buildStandardAdminWhere } from '../common/apply-column-filters';
import { EVENT_COLUMN_FILTERS } from '../common/admin-filter-configs';

export interface EventRowDto {
  id: number;
  title: string;
  slug: string | null;
  poster: unknown;
  description: string | null;
  content: unknown;
  startDate: string | null;
  endDate: string | null;
  checkinStart: string | null;
  checkinEnd: string | null;
  checkoutStart: string | null;
  checkoutEnd: string | null;
  registrationStart: string | null;
  registrationEnd: string | null;
  organizer: string | null;
  location: string | null;
  address: string | null;
  qrCode: string | null;
  status: number;
  totalRegistrations: number;
  totalCheckins: number;
  totalCheckouts: number;
  allowCheckin: boolean;
  allowCheckout: boolean;
  requireFaceId: boolean;
  maxParticipants: number;
  format: number;
  onlineLink: string | null;
  schedule: unknown;
  createdBy: number | null;
  createdAt: string;
  updatedAt: string;
  deletedAt: string | null;
  isFeatured: boolean;
  featuredOrder: number;
  checkinCameraId: number | null;
  checkoutCameraId: number | null;
  checkinCameraName: string | null;
  checkoutCameraName: string | null;
  checkinCameraCode: string | null;
  checkoutCameraCode: string | null;
}

export interface ListEventsParams {
  page: number;
  limit: number;
  search?: string;
  status?: 'active' | 'deleted' | 'all';
  statusFilter?: number;
  updatedAtFrom?: string;
  updatedAtTo?: string;
  deletedAtFrom?: string;
  deletedAtTo?: string;
  filters?: Record<string, string>;
}

export interface ListEventsResult {
  data: EventRowDto[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
}

function toIso(
  value: Date | string | number | undefined | null,
): string | null {
  if (value == null) return null;
  if (value instanceof Date)
    return Number.isNaN(value.getTime()) ? null : value.toISOString();
  if (typeof value === 'number')
    return Number.isNaN(value) ? null : new Date(value).toISOString();
  if (typeof value === 'string' && value.trim()) {
    const ms = Date.parse(value);
    return Number.isNaN(ms) ? null : new Date(ms).toISOString();
  }
  return null;
}

function mapRow(r: Event): EventRowDto {
  return {
    id: r.id,
    title: r.title,
    slug: r.slug ?? null,
    poster: normalizePosterField(r.poster),
    description: r.description ?? null,
    content:
      r.content != null
        ? typeof r.content === 'string'
          ? JSON.parse(r.content)
          : r.content
        : null,
    startDate: toIso(r.startDate),
    endDate: toIso(r.endDate),
    checkinStart: toIso(r.checkinStart),
    checkinEnd: toIso(r.checkinEnd),
    checkoutStart: toIso(r.checkoutStart),
    checkoutEnd: toIso(r.checkoutEnd),
    registrationStart: toIso(r.registrationStart),
    registrationEnd: toIso(r.registrationEnd),
    organizer: r.organizer ?? null,
    location: r.location ?? null,
    address: r.address ?? null,
    qrCode: r.qrCode ?? null,
    status: r.status,
    totalRegistrations: r.totalRegistrations,
    totalCheckins: r.totalCheckins,
    totalCheckouts: r.totalCheckouts,
    allowCheckin: r.allowCheckin,
    allowCheckout: r.allowCheckout,
    requireFaceId: r.requireFaceId,
    maxParticipants: r.maxParticipants,
    format: r.format,
    onlineLink: r.onlineLink ?? null,
    schedule: r.schedule ?? null,
    createdBy: r.createdBy?.id ?? null,
    createdAt: toIso(r.createdAt) ?? '',
    updatedAt: toIso(r.updatedAt) ?? '',
    deletedAt: toIso(r.deletedAt),
    isFeatured: r.isFeatured ?? false,
    featuredOrder: r.featuredOrder ?? 0,
    checkinCameraId: r.checkinCamera?.id ?? null,
    checkoutCameraId: r.checkoutCamera?.id ?? null,
    checkinCameraName: r.checkinCamera?.name ?? null,
    checkoutCameraName: r.checkoutCamera?.name ?? null,
    checkinCameraCode: r.checkinCamera?.code ?? null,
    checkoutCameraCode: r.checkoutCamera?.code ?? null,
  };
}

const EVENT_CAMERA_POPULATE = ['checkinCamera', 'checkoutCamera'] as const;

@Injectable()
export class EventsService {
  constructor(private readonly em: EntityManager) {}

  async list(params: ListEventsParams): Promise<ListEventsResult> {
    const { page, limit, skip } = normalizePageLimit(
      params.page,
      params.limit,
      ADMIN_TABLE_EXPORT_MAX_LIMIT,
    );
    const where = buildStandardAdminWhere({
      ...params,
      searchFields: ['title', 'organizer', 'location'],
      filterConfig: EVENT_COLUMN_FILTERS,
    });
    const whereQuery = where as FilterQuery<Event>;
    const [rows, total] = await Promise.all([
      this.em.find(Event, whereQuery, {
        populate: [...EVENT_CAMERA_POPULATE],
        orderBy: { updatedAt: 'DESC' },
        offset: skip,
        limit,
      }),
      this.em.count(Event, whereQuery),
    ]);
    return {
      data: rows.map(mapRow),
      pagination: paginationMeta(page, limit, total),
    };
  }

  async getById(id: string): Promise<EventRowDto | null> {
    const r = await this.em.findOne(
      Event,
      { id: toEntityId(id) },
      { populate: [...EVENT_CAMERA_POPULATE] },
    );
    if (!r) return null;
    return mapRow(r);
  }

  private applyEventCameras(event: Event, data: Record<string, unknown>): void {
    if (data.checkinCameraId !== undefined) {
      const raw = data.checkinCameraId;
      const id = raw === null || raw === '' ? '' : String(raw).trim();
      event.checkinCamera = id
        ? this.em.getReference(Camera, toEntityId(id))
        : null;
    }
    if (data.checkoutCameraId !== undefined) {
      const raw = data.checkoutCameraId;
      const id = raw === null || raw === '' ? '' : String(raw).trim();
      event.checkoutCamera = id
        ? this.em.getReference(Camera, toEntityId(id))
        : null;
    }
  }

  private async syncCamerasForEvent(event: Event): Promise<void> {
    const eventId = event.id;
    const selected = new Set(
      [event.checkinCamera?.id, event.checkoutCamera?.id].filter(
        (id): id is number => typeof id === 'number' && id > 0,
      ),
    );

    for (const cameraId of selected) {
      const camera = await this.em.findOne(Camera, {
        id: cameraId,
        deletedAt: null,
      });
      if (camera) {
        camera.linkedEvent = this.em.getReference(Event, toEntityId(eventId));
      }
    }

    const previouslyLinked = await this.em.find(Camera, {
      linkedEvent: eventId,
      deletedAt: null,
    } as FilterQuery<Camera>);

    for (const camera of previouslyLinked) {
      if (!selected.has(camera.id)) {
        camera.linkedEvent = null;
      }
    }

    await this.em.flush();
  }

  async create(data: Record<string, unknown>): Promise<EventRowDto> {
    const created = new Event();
    Object.assign(created, {
      title: data.title,
      slug: data.slug ?? null,
      poster:
        data.poster === undefined || data.poster === null
          ? null
          : normalizePosterField(data.poster),
      description: data.description ?? null,
      content: data.content ?? null,
      startDate: data.startDate ?? null,
      endDate: data.endDate ?? null,
      checkinStart: data.checkinStart ?? null,
      checkinEnd: data.checkinEnd ?? null,
      checkoutStart: data.checkoutStart ?? null,
      checkoutEnd: data.checkoutEnd ?? null,
      registrationStart: data.registrationStart ?? null,
      registrationEnd: data.registrationEnd ?? null,
      organizer: data.organizer ?? null,
      location: data.location ?? null,
      address: data.address ?? null,
      qrCode: data.qrCode ?? null,
      status: data.status ?? 1,
      totalRegistrations: 0,
      totalCheckins: 0,
      totalCheckouts: 0,
      allowCheckin: data.allowCheckin ?? true,
      allowCheckout: data.allowCheckout ?? true,
      requireFaceId: data.requireFaceId ?? false,
      maxParticipants: data.maxParticipants ?? 0,
      format: data.format ?? 'offline',
      onlineLink: data.onlineLink ?? null,
      schedule: data.schedule ?? null,
      isFeatured: Boolean(data.isFeatured),
      featuredOrder:
        typeof data.featuredOrder === 'number'
          ? data.featuredOrder
          : Number(data.featuredOrder) || 0,
    });
    this.applyEventCameras(created, data);
    await this.em.persistAndFlush(created);
    await this.syncCamerasForEvent(created);
    await this.em.populate(created, [...EVENT_CAMERA_POPULATE]);
    return mapRow(created);
  }

  async update(
    id: string,
    data: Record<string, unknown>,
  ): Promise<EventRowDto | null> {
    const existing = await this.em.findOne(Event, { id: toEntityId(id) });
    if (!existing) return null;
    const fields = [
      'title',
      'slug',
      'poster',
      'description',
      'content',
      'startDate',
      'endDate',
      'checkinStart',
      'checkinEnd',
      'checkoutStart',
      'checkoutEnd',
      'registrationStart',
      'registrationEnd',
      'organizer',
      'location',
      'address',
      'qrCode',
      'status',
      'allowCheckin',
      'allowCheckout',
      'requireFaceId',
      'maxParticipants',
      'format',
      'onlineLink',
      'schedule',
      'isFeatured',
      'featuredOrder',
    ] as const;
    for (const f of fields) {
      if (data[f] === undefined) continue;
      if (f === 'isFeatured') {
        existing.isFeatured = Boolean(data.isFeatured);
        continue;
      }
      if (f === 'featuredOrder') {
        existing.featuredOrder =
          typeof data.featuredOrder === 'number'
            ? data.featuredOrder
            : Number(data.featuredOrder) || 0;
        continue;
      }
      if (f === 'poster') {
        existing.poster =
          data.poster === null || data.poster === undefined
            ? null
            : normalizePosterField(data.poster);
        continue;
      }
      (existing as unknown as Record<string, unknown>)[f] = data[f];
    }
    this.applyEventCameras(existing, data);
    await this.em.persistAndFlush(existing);
    await this.syncCamerasForEvent(existing);
    await this.em.populate(existing, [...EVENT_CAMERA_POPULATE]);
    return mapRow(existing);
  }

  async softDelete(id: string): Promise<boolean> {
    const r = await this.em.findOne(Event, { id: toEntityId(id) });
    if (!r || r.deletedAt) return false;
    r.deletedAt = new Date();
    await this.em.persistAndFlush(r);
    return true;
  }

  async restore(id: string): Promise<boolean> {
    const r = await this.em.findOne(Event, { id: toEntityId(id) });
    if (!r || !r.deletedAt) return false;
    r.deletedAt = null;
    await this.em.persistAndFlush(r);
    return true;
  }

  async hardDelete(id: string): Promise<boolean> {
    const r = await this.em.findOne(Event, { id: toEntityId(id) });
    if (!r) return false;
    await this.em.removeAndFlush(r);
    return true;
  }
  async bulk(action: BulkAction, ids: string[]): Promise<BulkResult> {
    return applyBulkAction(this.em, Event, action, ids, { label: 'su kien' });
  }
}

src/face-data/face-data.controller.ts.content:
import {
  ApiTags,
  ApiOperation,
  ApiHeader,
  ApiBody,
  ApiResponse,
} from '@nestjs/swagger';
import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Body,
  Param,
  Query,
  Headers,
  Res,
  Logger,
} from '@nestjs/common';
import type { Response } from 'express';
import { FaceDataService } from './face-data.service';
import {
  createSuccessResponse,
  createErrorResponse,
} from '../common/api-response';
import { Permissions } from '../common/permissions.decorator';
import { PERMISSIONS } from '../config/permissions';
import { APP_HEADERS, ADMIN_ROUTES } from '../config/constants';
import { isBulkAction, type BulkAction } from '../common/bulk-actions';
import { parseAdminListLimit } from '../common/parse-list-query';

@ApiTags('FaceData')
@Permissions(PERMISSIONS.FACE_DATA_VIEW)
@Controller(ADMIN_ROUTES.FACE_DATA)
export class FaceDataController {
  private readonly logger = new Logger(FaceDataController.name);

  constructor(private readonly faceDataService: FaceDataService) {}

  private getUserId(
    headers: Record<string, string | undefined>,
  ): string | null {
    const id = headers[APP_HEADERS.USER_ID]?.trim();
    return id || null;
  }

  private unauthorized(res: Response): Response {
    const { statusCode, body } = createErrorResponse('Thiếu header X-User-Id', {
      status: 401,
    });
    return res.status(statusCode).json(body);
  }

  @Get()
  @ApiOperation({ summary: 'List face data with pagination' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async list(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Query('page') page?: string,
    @Query('limit') limit?: string,
    @Query('userId') userId?: string,
  ) {
    this.logger.log(`list page=${page ?? 1} limit=${limit ?? 10}`);
    const authUserId = this.getUserId(headers);
    if (!authUserId) return this.unauthorized(res);
    const result = await this.faceDataService.list({
      page: Math.max(1, parseInt(String(page), 10) || 1),
      limit: parseAdminListLimit(limit, 10),
      userId: userId?.trim(),
    });
    const { statusCode, body } = createSuccessResponse({
      data: result.data,
      pagination: result.pagination,
    });
    return res.status(statusCode).json(body);
  }

  @Get(':id')
  @ApiOperation({ summary: 'Get face data by ID' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async getById(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const row = await this.faceDataService.getById(id);
    if (!row) {
      const { statusCode, body } = createErrorResponse(
        'Không tìm thấy face data',
        { status: 404 },
      );
      return res.status(statusCode).json(body);
    }
    const { statusCode, body } = createSuccessResponse(row);
    return res.status(statusCode).json(body);
  }

  @Post()
  @Permissions(PERMISSIONS.FACE_DATA_CREATE)
  @ApiOperation({ summary: 'Create new face data' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async create(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Body()
    body: {
      imagePath: string;
      userId?: string;
      status?: number;
    },
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    if (!body?.imagePath?.trim()) {
      const { statusCode, body: errBody } = createErrorResponse(
        'imagePath là bắt buộc',
        { status: 400 },
      );
      return res.status(statusCode).json(errBody);
    }
    const created = await this.faceDataService.create({
      imagePath: body.imagePath.trim(),
      userId: body.userId?.trim() ?? null,
      status: body.status,
    });
    const { statusCode, body: okBody } = createSuccessResponse(created, {
      status: 201,
    });
    return res.status(statusCode).json(okBody);
  }

  @Put(':id')
  @Permissions(PERMISSIONS.FACE_DATA_UPDATE)
  @ApiOperation({ summary: 'Update face data by ID' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async update(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
    @Body()
    body: {
      imagePath?: string;
      status?: number;
    },
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const updated = await this.faceDataService.update(id, {
      imagePath: body?.imagePath?.trim(),
      status: body?.status,
    });
    if (!updated) {
      const { statusCode, body: errBody } = createErrorResponse(
        'Không tìm thấy face data',
        { status: 404 },
      );
      return res.status(statusCode).json(errBody);
    }
    const { statusCode, body: okBody } = createSuccessResponse(updated);
    return res.status(statusCode).json(okBody);
  }

  @Delete(':id/hard-delete')
  @Permissions(PERMISSIONS.FACE_DATA_HARD_DELETE)
  @ApiOperation({ summary: 'Hard delete face data permanently' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async hardDelete(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const ok = await this.faceDataService.hardDelete(id);
    if (!ok) {
      const { statusCode, body } = createErrorResponse(
        'Không tìm thấy face data',
        { status: 404 },
      );
      return res.status(statusCode).json(body);
    }
    const { statusCode, body } = createSuccessResponse(undefined, {
      message: 'Đã xóa vĩnh viễn face data',
    });
    return res.status(statusCode).json(body);
  }

  @Delete(':id')
  @Permissions(PERMISSIONS.FACE_DATA_DELETE)
  @ApiOperation({ summary: 'Soft delete face data' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async softDelete(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const ok = await this.faceDataService.softDelete(id);
    if (!ok) {
      const { statusCode, body } = createErrorResponse(
        'Face data không tồn tại hoặc đã bị xóa',
        { status: 404 },
      );
      return res.status(statusCode).json(body);
    }
    const { statusCode, body } = createSuccessResponse(undefined, {
      message: 'Đã xóa face data',
    });
    return res.status(statusCode).json(body);
  }

  @Post(':id/restore')
  @Permissions(PERMISSIONS.FACE_DATA_RESTORE)
  @ApiOperation({ summary: 'Restore soft-deleted face data' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async restore(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const ok = await this.faceDataService.restore(id);
    if (!ok) {
      const { statusCode, body } = createErrorResponse(
        'Face data không tồn tại hoặc chưa bị xóa',
        { status: 404 },
      );
      return res.status(statusCode).json(body);
    }
    const { statusCode, body } = createSuccessResponse(undefined, {
      message: 'Đã khôi phục face data',
    });
    return res.status(statusCode).json(body);
  }
  @Post('bulk')
  @Permissions(PERMISSIONS.FACE_DATA_MANAGE)
  @ApiOperation({ summary: 'Bulk action on khuon mats' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  @ApiBody({ description: 'Bulk action with ids' })
  @ApiResponse({ status: 200, description: 'Bulk action completed' })
  @ApiResponse({ status: 400, description: 'Invalid action' })
  async bulk(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Body() body: { action?: string; ids?: string[] },
  ) {
    const userId = this.getUserId(headers);
    if (!userId) {
      return this.unauthorized(res);
    }
    const action = body?.action;
    const ids = Array.isArray(body?.ids) ? body.ids : [];
    if (!action || !isBulkAction(action)) {
      const { statusCode, body: errBody } = createErrorResponse(
        'Action khong hop le',
        { status: 400 },
      );
      return res.status(statusCode).json(errBody);
    }
    const result = await this.faceDataService.bulk(action, ids);
    const { statusCode, body: okBody } = createSuccessResponse(
      { affected: result.affected, message: result.message },
      { message: result.message },
    );
    return res.status(statusCode).json(okBody);
  }
}

