/**
 * Socket.IO event types tương thích với tuyen-sinh-admin
 */

export type SocketNotificationKind =
  | 'message'
  | 'system'
  | 'announcement'
  | 'alert'
  | 'warning'
  | 'success'
  | 'info';

export interface SocketNotificationPayload {
  id: number;
  kind: SocketNotificationKind;
  title: string;
  description?: string | null;
  fromUserId?: string;
  toUserId?: string | number;
  replyToId?: string;
  timestamp: number;
  read?: boolean;
  actionUrl?: string | null;
  metadata?: Record<string, unknown> | null;
  userEmail?: string | null;
  userName?: string | null;
}

export interface SocketData {
  userId: number;
  role?: string;
  /** Id phiên đăng nhập (admin); có thì server join client vào room session:${sessionId} để nhận session:revoked */
  sessionId?: string;
}

export interface SessionRowDto {
  id: number;
  userId: number;
  userName: string | null;
  userEmail: string;
  accessToken: string;
  refreshToken: string;
  userAgent: string | null;
  ipAddress: string | null;
  isActive: boolean;
  expiresAt: string;
  lastActivity: string;
  createdAt: string;
  deletedAt: null;
}

export const MAX_HTTP_BUFFER_SIZE = 5 * 1024 * 1024; // 5MB
export const SOCKET_PATH = '/api/socket';

export function userRoom(userId: string | number): string {
  return `user:${userId}`;
}

export function conversationRoom(
  a: string | number,
  b: string | number,
): string {
  const sa = String(a);
  const sb = String(b);
  const [minId, maxId] = sa < sb ? [sa, sb] : [sb, sa];
  return `conversation:${minId}:${maxId}`;
}

export function sessionRoom(sessionId: string): string {
  return `session:${sessionId}`;
}

export function roleRoom(role: string): string {
  return `role:${role}`;
}

export function eventRoom(eventId: string | number): string {
  return `event:${eventId}`;
}

export type EventAttendanceSocketPayload = {
  kind: 'checkin' | 'checkout';
  eventId: number;
  at: string;
  email: string;
  fullName: string;
  source: 'hanet' | 'manual';
  deviceId?: string | null;
  deviceName?: string | null;
  registrationId?: string | number | null;
  checkinId?: string | null;
  duplicate?: boolean;
  /** Trạng thái sau cập nhật — client patch cache chính xác kể cả reset thủ công. */
  hasCheckin?: boolean;
  hasCheckout?: boolean;
};

/** Invalidate React Query cache trên admin clients sau mutation CRUD. */
export type AdminCacheInvalidatePayload = {
  resource: string;
  action:
    | 'create'
    | 'update'
    | 'delete'
    | 'restore'
    | 'purge'
    | 'bulk'
    | 'mutate';
  id?: string | number;
};

/** Duyệt / đổi trạng thái — đồng bộ giữa nhiều tài khoản admin (hợp đồng @workspace/api-client/realtime). */
export type AdminStatusChangePayload = {
  resource: string;
  id: number;
  status: string;
  previousStatus?: string;
  title?: string;
  description?: string | null;
  actionUrl?: string | null;
  actorUserId?: string;
};

/** Admin duyệt/từ chối liên kết phụ huynh – học sinh. */
export type ParentStudentReviewSocketPayload = {
  id: number;
  parentId: number;
  studentCode: string;
  studentName: string | null;
  status: 'approved' | 'rejected';
  reviewedAt: string;
  reviewedBy?: string;
};

src/speakers/speakers.controller.ts.content:
import {
  ApiTags,
  ApiOperation,
  ApiHeader,
  ApiBody,
  ApiResponse,
} from '@nestjs/swagger';
import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Body,
  Param,
  Query,
  Headers,
  Res,
  Logger,
} from '@nestjs/common';
import { Permissions } from '../common/permissions.decorator';
import { PERMISSIONS } from '../config/permissions';
import type { Response } from 'express';
import { SpeakersService } from './speakers.service';
import {
  createSuccessResponse,
  createErrorResponse,
} from '../common/api-response';
import { APP_HEADERS, ADMIN_ROUTES } from '../config/constants';
import { isBulkAction, type BulkAction } from '../common/bulk-actions';
import { parseAdminListLimit } from '../common/parse-list-query';
import { parseColumnFiltersFromQuery } from '../common/parse-column-filters';

@ApiTags('Speakers')
@Controller(ADMIN_ROUTES.SPEAKERS)
@Permissions(PERMISSIONS.SPEAKERS_VIEW)
export class SpeakersController {
  private readonly logger = new Logger(SpeakersController.name);

  constructor(private readonly speakersService: SpeakersService) {}

  private getUserId(
    headers: Record<string, string | undefined>,
  ): string | null {
    const id = headers[APP_HEADERS.USER_ID]?.trim();
    return id || null;
  }

  private unauthorized(res: Response): Response {
    const { statusCode, body } = createErrorResponse('Thiếu header X-User-Id', {
      status: 401,
    });
    return res.status(statusCode).json(body);
  }

  @Get()
  @ApiOperation({ summary: 'List speakers with pagination' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async list(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Query('page') page?: string,
    @Query('limit') limit?: string,
    @Query('search') search?: string,
    @Query('status') status?: string,
    @Query('speakerStatus') speakerStatus?: string,
    @Query('updatedAtFrom') updatedAtFrom?: string,
    @Query('updatedAtTo') updatedAtTo?: string,
    @Query('deletedAtFrom') deletedAtFrom?: string,
    @Query('deletedAtTo') deletedAtTo?: string,
    @Query() query?: Record<string, string>,
  ) {
    this.logger.log(`list page=${page ?? 1} limit=${limit ?? 10}`);
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const result = await this.speakersService.list({
      page: Math.max(1, parseInt(String(page), 10) || 1),
      limit: parseAdminListLimit(limit, 10),
      search: search?.trim(),
      status: (status as 'active' | 'deleted' | 'all') ?? 'active',
      speakerStatus:
        speakerStatus !== undefined ? parseInt(speakerStatus, 10) : undefined,
      updatedAtFrom: updatedAtFrom?.trim() || undefined,
      updatedAtTo: updatedAtTo?.trim() || undefined,
      deletedAtFrom: deletedAtFrom?.trim() || undefined,
      deletedAtTo: deletedAtTo?.trim() || undefined,
      filters: parseColumnFiltersFromQuery(query),
    });
    const { statusCode, body } = createSuccessResponse({
      data: result.data,
      pagination: result.pagination,
    });
    return res.status(statusCode).json(body);
  }

  @Get(':id')
  @ApiOperation({ summary: 'Get speaker by ID' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async getById(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const row = await this.speakersService.getById(Number(id));
    if (!row) {
      const { statusCode, body } = createErrorResponse(
        'Không tìm thấy diễn giả',
        { status: 404 },
      );
      return res.status(statusCode).json(body);
    }
    const { statusCode, body } = createSuccessResponse(row);
    return res.status(statusCode).json(body);
  }

  @Permissions(PERMISSIONS.SPEAKERS_CREATE)
  @Post()
  @ApiOperation({ summary: 'Create new speaker' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async create(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Body()
    body: {
      name: string;
      title?: string;
      organization?: string;
      bio?: string;
      avatar?: string;
      email?: string;
      phone?: string;
      status?: number;
    },
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    if (!body?.name?.trim()) {
      const { statusCode, body: errBody } = createErrorResponse(
        'name là bắt buộc',
        { status: 400 },
      );
      return res.status(statusCode).json(errBody);
    }
    const created = await this.speakersService.create({
      name: body.name.trim(),
      title: body.title?.trim() ?? null,
      organization: body.organization?.trim() ?? null,
      bio: body.bio?.trim() ?? null,
      avatar: body.avatar?.trim() ?? null,
      email: body.email?.trim() ?? null,
      phone: body.phone?.trim() ?? null,
      status: body.status,
    });
    const { statusCode, body: okBody } = createSuccessResponse(created, {
      status: 201,
    });
    return res.status(statusCode).json(okBody);
  }

  @Permissions(PERMISSIONS.SPEAKERS_UPDATE)
  @Put(':id')
  @ApiOperation({ summary: 'Update speaker by ID' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async update(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
    @Body()
    body: {
      name?: string;
      title?: string;
      organization?: string;
      bio?: string;
      avatar?: string;
      email?: string;
      phone?: string;
      status?: number;
    },
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const updated = await this.speakersService.update(Number(id), {
      name: body?.name?.trim(),
      title:
        body?.title !== undefined ? (body.title?.trim() ?? null) : undefined,
      organization:
        body?.organization !== undefined
          ? (body.organization?.trim() ?? null)
          : undefined,
      bio: body?.bio !== undefined ? (body.bio?.trim() ?? null) : undefined,
      avatar:
        body?.avatar !== undefined ? (body.avatar?.trim() ?? null) : undefined,
      email:
        body?.email !== undefined ? (body.email?.trim() ?? null) : undefined,
      phone:
        body?.phone !== undefined ? (body.phone?.trim() ?? null) : undefined,
      status: body?.status,
    });
    if (!updated) {
      const { statusCode, body: errBody } = createErrorResponse(
        'Không tìm thấy diễn giả',
        { status: 404 },
      );
      return res.status(statusCode).json(errBody);
    }
    const { statusCode, body: okBody } = createSuccessResponse(updated);
    return res.status(statusCode).json(okBody);
  }

  @Permissions(PERMISSIONS.SPEAKERS_MANAGE)
  @Delete(':id/hard-delete')
  @ApiOperation({ summary: 'Hard delete speaker permanently' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async hardDelete(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const ok = await this.speakersService.hardDelete(Number(id));
    if (!ok) {
      const { statusCode, body } = createErrorResponse(
        'Không tìm thấy diễn giả',
        { status: 404 },
      );
      return res.status(statusCode).json(body);
    }
    const { statusCode, body } = createSuccessResponse(undefined, {
      message: 'Đã xóa vĩnh viễn diễn giả',
    });
    return res.status(statusCode).json(body);
  }

  @Permissions(PERMISSIONS.SPEAKERS_DELETE)
  @Delete(':id')
  @ApiOperation({ summary: 'Soft delete speaker' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async softDelete(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const ok = await this.speakersService.softDelete(Number(id));
    if (!ok) {
      const { statusCode, body } = createErrorResponse(
        'Diễn giả không tồn tại hoặc đã bị xóa',
        { status: 404 },
      );
      return res.status(statusCode).json(body);
    }
    const { statusCode, body } = createSuccessResponse(undefined, {
      message: 'Đã xóa diễn giả',
    });
    return res.status(statusCode).json(body);
  }

  @Permissions(PERMISSIONS.SPEAKERS_RESTORE)
  @Post(':id/restore')
  @ApiOperation({ summary: 'Restore soft-deleted speaker' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async restore(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    const userId = this.getUserId(headers);
    if (!userId) return this.unauthorized(res);
    const ok = await this.speakersService.restore(Number(id));
    if (!ok) {
      const { statusCode, body } = createErrorResponse(
        'Diễn giả không tồn tại hoặc chưa bị xóa',
        { status: 404 },
      );
      return res.status(statusCode).json(body);
    }
    const { statusCode, body } = createSuccessResponse(undefined, {
      message: 'Đã khôi phục diễn giả',
    });
    return res.status(statusCode).json(body);
  }
  @Post('bulk')
  @Permissions(PERMISSIONS.SPEAKERS_MANAGE)
  @ApiOperation({ summary: 'Bulk action on dien gias' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  @ApiBody({ description: 'Bulk action with ids' })
  @ApiResponse({ status: 200, description: 'Bulk action completed' })
  @ApiResponse({ status: 400, description: 'Invalid action' })
  async bulk(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Body() body: { action?: string; ids?: string[] },
  ) {
    const userId = this.getUserId(headers);
    if (!userId) {
      return this.unauthorized(res);
    }
    const action = body?.action;
    const ids = Array.isArray(body?.ids) ? body.ids : [];
    if (!action || !isBulkAction(action)) {
      const { statusCode, body: errBody } = createErrorResponse(
        'Action khong hop le',
        { status: 400 },
      );
      return res.status(statusCode).json(errBody);
    }
    const result = await this.speakersService.bulk(action, ids);
    const { statusCode, body: okBody } = createSuccessResponse(
      { affected: result.affected, message: result.message },
      { message: result.message },
    );
    return res.status(statusCode).json(okBody);
  }
}

