import * as fs from 'fs';
import * as path from 'path';

export type ImportReferenceManifest = {
  source: string;
  exportedAt: string;
  description?: string;
  expectedCounts: Record<string, number>;
  notes?: Record<string, string>;
};

const DEFAULT_REFERENCE_REL = 'data/import-reference-2026-06-10.json';

function resolveReferencePath(relOrAbs: string): string {
  if (path.isAbsolute(relOrAbs)) return relOrAbs;
  const candidates = [
    path.join(process.cwd(), relOrAbs),
    path.join(process.cwd(), '..', '..', relOrAbs),
  ];
  for (const candidate of candidates) {
    if (fs.existsSync(candidate)) return candidate;
  }
  return candidates[0];
}

export function getImportReferenceFilePath(): string {
  const rel =
    process.env.SYSTEM_IMPORT_REFERENCE_FILE?.trim() || DEFAULT_REFERENCE_REL;
  return resolveReferencePath(rel);
}

export function loadImportReferenceManifest(): ImportReferenceManifest | null {
  const filePath = getImportReferenceFilePath();
  if (!fs.existsSync(filePath)) return null;
  try {
    const raw = JSON.parse(
      fs.readFileSync(filePath, 'utf8'),
    ) as ImportReferenceManifest;
    if (!raw?.expectedCounts || typeof raw.expectedCounts !== 'object') {
      return null;
    }
    return raw;
  } catch {
    return null;
  }
}

export type ImportVerificationModel = {
  exportModelName: string;
  expected: number;
  actual: number;
  status: 'ok' | 'over' | 'under';
  note?: string;
};

export type ImportVerificationResult = {
  referenceSource: string;
  referenceExportedAt: string;
  referenceFile: string;
  isComplete: boolean;
  matchedModels: number;
  mismatchedModels: number;
  expectedBusinessTotalRows: number;
  actualBusinessTotalRows: number;
  models: ImportVerificationModel[];
};

export function buildImportVerification(
  manifest: ImportReferenceManifest,
  referenceFile: string,
  actualByModel: Map<string, { rowCount: number; note?: string }>,
): ImportVerificationResult {
  const models: ImportVerificationModel[] = [];
  let matchedModels = 0;
  let mismatchedModels = 0;
  let expectedBusinessTotalRows = 0;
  let actualBusinessTotalRows = 0;

  for (const [exportModelName, expected] of Object.entries(
    manifest.expectedCounts,
  )) {
    if (expected <= 0) continue;
    const actualEntry = actualByModel.get(exportModelName);
    const actual = actualEntry?.rowCount ?? 0;
    const status: ImportVerificationModel['status'] =
      actual === expected ? 'ok' : actual > expected ? 'over' : 'under';
    if (status === 'ok') matchedModels += 1;
    else mismatchedModels += 1;
    expectedBusinessTotalRows += expected;
    actualBusinessTotalRows += actual;
    models.push({
      exportModelName,
      expected,
      actual,
      status,
      note: actualEntry?.note ?? manifest.notes?.[exportModelName],
    });
  }

  models.sort((a, b) => {
    if (a.status !== b.status) {
      const rank = { under: 0, over: 1, ok: 2 };
      return rank[a.status] - rank[b.status];
    }
    return b.expected - a.expected;
  });

  return {
    referenceSource: manifest.source,
    referenceExportedAt: manifest.exportedAt,
    referenceFile,
    isComplete: mismatchedModels === 0,
    matchedModels,
    mismatchedModels,
    expectedBusinessTotalRows,
    actualBusinessTotalRows,
    models,
  };
}

src/system/legacy-import-id-map.ts.content:
import type { EntityManager } from '@mikro-orm/core';
import { coerceImportPrimaryKey } from '../common/entity-id';
import { Setting } from '../entities/setting.entity';

export const IMPORT_ID_MAP_GROUP = 'import_id_map';

export function importIdMapSettingKey(model: string, legacyId: string): string {
  return `import_id_map:${model}:${legacyId}`;
}

/** Khóa legacy từ export (UUID/CUID) — không nhận id số đã migrate. */
export function exportLegacyKey(raw: unknown): string | undefined {
  const pk = coerceImportPrimaryKey(raw);
  if (pk != null) return undefined;
  if (raw == null || raw === '') return undefined;
  const s = String(raw).trim();
  return s || undefined;
}

/**
 * Ánh xạ id export cũ → id int mới trong cùng phiên import (và lưu settings để dùng qua nhiều request).
 */
export class LegacyImportIdMap {
  private mem = new Map<string, number>();

  private memKey(model: string, legacyId: string): string {
    return `${model}:${legacyId}`;
  }

  remember(model: string, legacyId: string, newId: number): void {
    this.mem.set(this.memKey(model, legacyId), newId);
  }

  recall(model: string, legacyId: string): number | undefined {
    return this.mem.get(this.memKey(model, legacyId));
  }

  async persist(
    em: EntityManager,
    model: string,
    legacyId: string,
    newId: number,
  ): Promise<void> {
    this.remember(model, legacyId, newId);
    const key = importIdMapSettingKey(model, legacyId);
    let row = await em.findOne(Setting, { key });
    const now = new Date();
    if (!row) {
      row = new Setting();
      row.key = key;
      row.group = IMPORT_ID_MAP_GROUP;
      row.value = newId;
      row.createdAt = now;
      row.updatedAt = now;
    } else {
      row.value = newId;
      row.group = IMPORT_ID_MAP_GROUP;
      row.updatedAt = now;
    }
    em.persist(row);
  }

  async resolve(
    em: EntityManager,
    model: string,
    raw: unknown,
  ): Promise<number | undefined> {
    const pk = coerceImportPrimaryKey(raw);
    if (pk != null) return pk;
    const legacy = exportLegacyKey(raw);
    if (!legacy) return undefined;

    const cached = this.recall(model, legacy);
    if (cached != null) return cached;

    const row = await em.findOne(Setting, {
      key: importIdMapSettingKey(model, legacy),
      group: IMPORT_ID_MAP_GROUP,
    });
    if (row?.value == null) return undefined;
    const n =
      typeof row.value === 'number' ? row.value : Number(String(row.value));
    if (!Number.isFinite(n) || n <= 0) return undefined;
    this.remember(model, legacy, n);
    return n;
  }
}

src/system/system.controller.ts.content:
import {
  Controller,
  Get,
  Post,
  Body,
  Headers,
  Res,
  Logger,
  Query,
  UsePipes,
  ValidationPipe,
  UploadedFile,
  UseInterceptors,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { SkipThrottle } from '@nestjs/throttler';
import type { Response } from 'express';
import { SystemService } from './system.service';
import { AuthService } from '../auth/auth.service';
import {
  createSuccessResponse,
  createErrorResponse,
} from '../common/api-response';
import {
  APP_HEADERS,
  ADMIN_ROUTES,
  AUTH_ROLE_NAMES,
} from '../config/constants';
import { Permissions } from '../common/permissions.decorator';
import { PERMISSIONS } from '../config/permissions';

/** Khớp admin `/data`: settings:manage|import|export hoặc system:manage|import. */
const SYSTEM_MAINTENANCE_PERMISSIONS: ReadonlySet<string> = new Set([
  PERMISSIONS.SYSTEM_MANAGE,
  PERMISSIONS.SYSTEM_IMPORT,
  PERMISSIONS.SETTINGS_MANAGE,
  PERMISSIONS.SETTINGS_IMPORT,
  PERMISSIONS.SETTINGS_EXPORT,
]);
const MAX_SYSTEM_EXCEL_FILE_BYTES = 50 * 1024 * 1024;

/** Import/export nhiều chunk — không áp dụng giới hạn 100 req/phút toàn cục. */
@SkipThrottle()
@Permissions(
  PERMISSIONS.SYSTEM_MANAGE,
  PERMISSIONS.SETTINGS_MANAGE,
  PERMISSIONS.SETTINGS_EXPORT,
  PERMISSIONS.SETTINGS_IMPORT,
)
@Controller(ADMIN_ROUTES.SYSTEM)
export class SystemController {
  private readonly logger = new Logger(SystemController.name);

  constructor(
    private readonly systemService: SystemService,
    private readonly authService: AuthService,
  ) {}

  private async canAccessSystemMaintenance(
    headers: Record<string, string | undefined>,
  ): Promise<boolean> {
    const userId = headers[APP_HEADERS.USER_ID]?.trim();
    if (!userId) return false;

    const payload = await this.authService.getAuthPayloadByUserId(userId);
    if (!payload) return false;

    if (
      payload.roles.some((role) => role.name === AUTH_ROLE_NAMES.SUPER_ADMIN)
    ) {
      return true;
    }

    return payload.permissions.some((p) =>
      SYSTEM_MAINTENANCE_PERMISSIONS.has(p),
    );
  }

  private logApiError(api: string, error: unknown, metadata?: unknown): void {
    const details =
      error instanceof Error
        ? {
            api,
            name: error.name,
            message: error.message,
            stack: error.stack ?? null,
            metadata: metadata ?? null,
          }
        : {
            api,
            message: String(error),
            stack: null,
            metadata: metadata ?? null,
          };
    this.logger.error(JSON.stringify(details));
  }

  @Get('models')
  async getModels(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
  ) {
    try {
      if (!(await this.canAccessSystemMaintenance(headers))) {
        const { statusCode, body } = createErrorResponse(
          'Unauthorized: Super Admin or system manage permission required',
          { status: 403 },
        );
        return res.status(statusCode).json(body);
      }

      const data = this.systemService.getModels();
      const { statusCode, body } = createSuccessResponse(data);
      return res.status(statusCode).json(body);
    } catch (error) {
      this.logApiError('GET /api/admin/system/models', error);
      const { statusCode, body } = createErrorResponse(
        'Internal Server Error',
        { status: 500 },
      );
      return res.status(statusCode).json(body);
    }
  }

  @Get('export')
  async exportData(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Query('model') model?: string,
  ) {
    try {
      if (!(await this.canAccessSystemMaintenance(headers))) {
        const { statusCode, body } = createErrorResponse(
          'Unauthorized: Super Admin or system manage permission required',
          { status: 403 },
        );
        return res.status(statusCode).json(body);
      }

      const data = await this.systemService.exportData(model);
      const { statusCode, body } = createSuccessResponse(data);
      return res.status(statusCode).json(body);
    } catch (error) {
      this.logApiError('GET /api/admin/system/export', error, { model });
      const { statusCode, body } = createErrorResponse(
        'Internal Server Error',
        { status: 500 },
      );
      return res.status(statusCode).json(body);
    }
  }

  @Get('export/excel')
  async exportExcelData(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Query('model') model?: string,
  ) {
    try {
      if (!(await this.canAccessSystemMaintenance(headers))) {
        const { statusCode, body } = createErrorResponse(
          'Unauthorized: Super Admin or system manage permission required',
          { status: 403 },
        );
        return res.status(statusCode).json(body);
      }

      const buffer = await this.systemService.exportExcelData(model);
      const now = new Date();
      const y = now.getFullYear();
      const m = String(now.getMonth() + 1).padStart(2, '0');
      const d = String(now.getDate()).padStart(2, '0');
      const dateStamp = `${y}-${m}-${d}`;
      const filename = model
        ? `hub-system-${model}-${dateStamp}.xlsx`
        : `hub-system-export-${dateStamp}.xlsx`;
      res.setHeader(
        'Content-Type',
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      );
      res.setHeader(
        'Content-Disposition',
        `attachment; filename="${filename}"`,
      );
      return res.status(200).send(buffer);
    } catch (error) {
      this.logApiError('GET /api/admin/system/export/excel', error, { model });
      const { statusCode, body } = createErrorResponse(
        'Internal Server Error',
        { status: 500 },
      );
      return res.status(statusCode).json(body);
    }
  }

  @Permissions(PERMISSIONS.SYSTEM_IMPORT, PERMISSIONS.SETTINGS_IMPORT)
  @Post('import')
  @UsePipes(
    new ValidationPipe({
      whitelist: false,
      forbidNonWhitelisted: false,
      forbidUnknownValues: false,
      transform: false,
    }),
  )
  async importData(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Query('model') model?: string,
    @Query('skipClear') skipClear?: string,
    @Query('stream') stream?: string,
    @Body() data?: Record<string, any[]>,
  ) {
    try {
      if (!(await this.canAccessSystemMaintenance(headers))) {
        const { statusCode, body } = createErrorResponse(
          'Unauthorized: Super Admin or system manage permission required',
          { status: 403 },
        );
        return res.status(statusCode).json(body);
      }

      if (!data || Object.keys(data).length === 0) {
        const { statusCode, body } = createErrorResponse(
          'Invalid data: No data provided',
          { status: 400 },
        );
        return res.status(statusCode).json(body);
      }

      if (stream === 'true') {
        res.setHeader('Content-Type', 'application/x-ndjson');
        res.setHeader('Transfer-Encoding', 'chunked');

        const onProgress = (event: object) => {
          if (!res.writableEnded) {
            res.write(JSON.stringify(event) + '\n');
          }
        };

        try {
          const result = await this.systemService.importData(
            data,
            model,
            skipClear === 'true',
            onProgress,
            headers[APP_HEADERS.USER_ID],
          );
          onProgress({ type: 'complete', ...result });
        } catch (error) {
          onProgress({
            type: 'error',
            message:
              error instanceof Error ? error.message : 'Internal Server Error',
          });
        } finally {
          if (!res.writableEnded) {
            res.end();
          }
        }
        return;
      }

      const result = await this.systemService.importData(
        data,
        model,
        skipClear === 'true',
        undefined,
        headers[APP_HEADERS.USER_ID],
      );
      const { statusCode, body } = createSuccessResponse(result);
      return res.status(statusCode).json(body);
    } catch (error) {
      this.logApiError('POST /api/admin/system/import', error, {
        model,
        skipClear,
        stream,
        modelCount: data ? Object.keys(data).length : 0,
      });
      const { statusCode, body } = createErrorResponse(
        error instanceof Error ? error.message : 'Internal Server Error',
        { status: 500 },
      );
      return res.status(statusCode).json(body);
    }
  }

  @Permissions(PERMISSIONS.SYSTEM_IMPORT, PERMISSIONS.SETTINGS_IMPORT)
  @Post('import/excel')
  @UseInterceptors(
    FileInterceptor('file', {
      limits: { fileSize: MAX_SYSTEM_EXCEL_FILE_BYTES },
    }),
  )
  async importExcelData(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Query('model') model?: string,
    @Query('skipClear') skipClear?: string,
    @Query('stream') stream?: string,
    @UploadedFile()
    file?: { buffer: Buffer; originalname?: string; mimetype?: string },
  ) {
    try {
      if (!(await this.canAccessSystemMaintenance(headers))) {
        const { statusCode, body } = createErrorResponse(
          'Unauthorized: Super Admin or system manage permission required',
          { status: 403 },
        );
        return res.status(statusCode).json(body);
      }

      if (!file?.buffer || file.buffer.length === 0) {
        const { statusCode, body } = createErrorResponse(
          'Invalid file: No Excel file uploaded',
          { status: 400 },
        );
        return res.status(statusCode).json(body);
      }

      if (stream === 'true') {
        res.setHeader('Content-Type', 'application/x-ndjson');
        res.setHeader('Transfer-Encoding', 'chunked');

        const onProgress = (event: object) => {
          if (!res.writableEnded) {
            res.write(JSON.stringify(event) + '\n');
          }
        };

        try {
          const result = await this.systemService.importExcelData(
            file.buffer,
            model,
            skipClear === 'true',
            onProgress,
            headers[APP_HEADERS.USER_ID],
          );
          onProgress({ type: 'complete', ...result });
        } catch (error) {
          onProgress({
            type: 'error',
            message:
              error instanceof Error ? error.message : 'Internal Server Error',
          });
        } finally {
          if (!res.writableEnded) {
            res.end();
          }
        }
        return;
      }

      const result = await this.systemService.importExcelData(
        file.buffer,
        model,
        skipClear === 'true',
        undefined,
        headers[APP_HEADERS.USER_ID],
      );
      const { statusCode, body } = createSuccessResponse(result);
      return res.status(statusCode).json(body);
    } catch (error) {
      this.logApiError('POST /api/admin/system/import/excel', error, {
        model,
        skipClear,
        stream,
        filename: file?.originalname ?? null,
      });
      const { statusCode, body } = createErrorResponse(
        error instanceof Error ? error.message : 'Internal Server Error',
        { status: 500 },
      );
      return res.status(statusCode).json(body);
    }
  }

  /** Khởi tạo roles + user mặc định + user_roles (+ page_contents nếu có file JSON trên server) — giống `pnpm run seed:superadmin`. */
  @Post('seed-bootstrap')
  async seedBootstrap(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
  ) {
    try {
      if (!(await this.canAccessSystemMaintenance(headers))) {
        const { statusCode, body } = createErrorResponse(
          'Unauthorized: Super Admin or system manage permission required',
          { status: 403 },
        );
        return res.status(statusCode).json(body);
      }

      const data = await this.systemService.runSuperadminBootstrapSeed();
      const { statusCode, body } = createSuccessResponse(data);
      return res.status(statusCode).json(body);
    } catch (error) {
      this.logApiError('POST /api/admin/system/seed-bootstrap', error);
      const { statusCode, body } = createErrorResponse(
        error instanceof Error ? error.message : 'Internal Server Error',
        { status: 500 },
      );
      return res.status(statusCode).json(body);
    }
  }

  @Permissions(PERMISSIONS.SYSTEM_IMPORT, PERMISSIONS.SETTINGS_IMPORT)
  @Get('import-config')
  async getImportConfig(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
  ) {
    try {
      if (!(await this.canAccessSystemMaintenance(headers))) {
        const { statusCode, body } = createErrorResponse(
          'Unauthorized: Super Admin or system manage permission required',
          { status: 403 },
        );
        return res.status(statusCode).json(body);
      }

      const data = this.systemService.getImportConfig();
      const { statusCode, body } = createSuccessResponse(data);
      return res.status(statusCode).json(body);
    } catch (error) {
      this.logApiError('GET /api/admin/system/import-config', error);
      const { statusCode, body } = createErrorResponse(
        error instanceof Error ? error.message : 'Internal Server Error',
        { status: 500 },
      );
      return res.status(statusCode).json(body);
    }
  }

  @Permissions(PERMISSIONS.SYSTEM_VIEW, PERMISSIONS.SETTINGS_MANAGE)
  @Get('database-schema')
  async getDatabaseSchema(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
  ) {
    try {
      if (!(await this.canAccessSystemMaintenance(headers))) {
        const { statusCode, body } = createErrorResponse(
          'Unauthorized: Super Admin or system manage permission required',
          { status: 403 },
        );
        return res.status(statusCode).json(body);
      }

      const data = await this.systemService.getDatabaseSchema();
      const { statusCode, body } = createSuccessResponse(data);
      return res.status(statusCode).json(body);
    } catch (error) {
      this.logApiError('GET /api/admin/system/database-schema', error);
      const { statusCode, body } = createErrorResponse(
        error instanceof Error ? error.message : 'Internal Server Error',
        { status: 500 },
      );
      return res.status(statusCode).json(body);
    }
  }
}

