import {
  mapZipPathToStoragePath,
  normalizeZipEntryPath,
} from './zip-path-mapper';

describe('normalizeZipEntryPath', () => {
  it('bỏ thư mục và file hệ thống', () => {
    expect(normalizeZipEntryPath('__MACOSX/foo')).toBeNull();
    expect(normalizeZipEntryPath('images/.DS_Store')).toBeNull();
    expect(normalizeZipEntryPath('images/folder/')).toBeNull();
  });

  it('giữ path hợp lệ', () => {
    expect(normalizeZipEntryPath('images/a.jpg')).toBe('images/a.jpg');
  });
});

describe('mapZipPathToStoragePath', () => {
  const all = (paths: string[]) => paths;

  it('giữ path đã có images/', () => {
    expect(
      mapZipPathToStoragePath(
        'images/admincp/buh_slidehome/a.jpg',
        all(['images/admincp/buh_slidehome/a.jpg']),
      ),
    ).toBe('images/admincp/buh_slidehome/a.jpg');
  });

  it('tìm images/ ở giữa path (ZIP nhiều wrapper)', () => {
    const paths = [
      'backup-2024/images/admincp/buh_tintuc_thumb/a.jpg',
      'backup-2024/images/admincp/buh_slidehome/b.jpg',
    ];
    expect(mapZipPathToStoragePath(paths[0], paths)).toBe(
      'images/admincp/buh_tintuc_thumb/a.jpg',
    );
  });

  it('bỏ uploads/ và giữ admincp legacy không ép images/', () => {
    const paths = ['uploads/images/admincp/foo.jpg'];
    expect(mapZipPathToStoragePath(paths[0], paths)).toBe(
      'images/admincp/foo.jpg',
    );
  });

  it('map admincp/ ở root ZIP — giữ admincp/ (tab tự nhận)', () => {
    const paths = [
      'admincp/buh_slidehome/slide.jpg',
      'admincp/buh_tintuc_thumb/thumb.jpg',
    ];
    expect(mapZipPathToStoragePath(paths[0], paths)).toBe(
      'admincp/buh_slidehome/slide.jpg',
    );
  });

  it('bỏ wrapper kho-luu-tru/ khi mọi entry cùng root', () => {
    const paths = [
      'kho-luu-tru/images/2026/03/a.jpg',
      'kho-luu-tru/images/2026/03/b.jpg',
    ];
    expect(mapZipPathToStoragePath(paths[0], paths)).toBe(
      'images/2026/03/a.jpg',
    );
  });

  it('folder tùy chỉnh không ép vào images/', () => {
    const paths = ['buh_custom_folder/photo.png'];
    expect(mapZipPathToStoragePath(paths[0], paths)).toBe(
      'buh_custom_folder/photo.png',
    );
  });
});

src/uploads/zip-path-mapper.ts.content:
import * as path from 'path';

const ZIP_PATH_PREFIX_STRIPS = [
  'uploads/',
  'data/',
  'storage/',
  'public/',
  'wwwroot/',
] as const;

const IMAGE_STORAGE_PREFIX = 'images/';
const FILE_STORAGE_PREFIX = 'files/';
const VIDEO_STORAGE_PREFIX = 'videos/';
const AUDIO_STORAGE_PREFIX = 'audio/';

/** Thư mục legacy CMS (admincp/...) nằm dưới uploads/images trên disk. */
const LEGACY_IMAGE_ROOT_MARKERS = ['admincp/'] as const;

export function normalizeZipEntryPath(raw: string): string | null {
  const normalized = raw.replace(/\\/g, '/').replace(/^\/+/, '');
  if (!normalized || normalized.endsWith('/')) return null;
  if (normalized.includes('..')) return null;
  if (normalized.startsWith('__MACOSX/') || normalized.includes('/__MACOSX/'))
    return null;
  const base = path.posix.basename(normalized);
  if (base === '.DS_Store' || base.startsWith('._')) return null;
  return normalized;
}

function sliceFromStorageRoot(normalized: string): string | null {
  const imagesIdx = normalized.indexOf(IMAGE_STORAGE_PREFIX);
  const filesIdx = normalized.indexOf(FILE_STORAGE_PREFIX);
  const videosIdx = normalized.indexOf(VIDEO_STORAGE_PREFIX);
  const audioIdx = normalized.indexOf(AUDIO_STORAGE_PREFIX);

  const hits = [
    { idx: imagesIdx, prefix: IMAGE_STORAGE_PREFIX },
    { idx: filesIdx, prefix: FILE_STORAGE_PREFIX },
    { idx: videosIdx, prefix: VIDEO_STORAGE_PREFIX },
    { idx: audioIdx, prefix: AUDIO_STORAGE_PREFIX },
  ]
    .filter((hit) => hit.idx >= 0)
    .sort((a, b) => a.idx - b.idx);

  if (hits.length > 0) {
    return normalized.slice(hits[0].idx);
  }
  return null;
}

function legacyImagePath(normalized: string): string | null {
  for (const marker of LEGACY_IMAGE_ROOT_MARKERS) {
    const idx = normalized.indexOf(marker);
    if (idx >= 0) {
      return normalized.slice(idx);
    }
  }
  return null;
}

function peelKnownPrefixes(normalized: string): string {
  let current = normalized;
  let changed = true;
  while (changed) {
    changed = false;
    for (const prefix of ZIP_PATH_PREFIX_STRIPS) {
      if (current.startsWith(prefix)) {
        current = current.slice(prefix.length);
        changed = true;
      }
    }
  }
  return current;
}

/**
 * Chuẩn hóa đường dẫn entry ZIP → relativePath trên kho (giữ cấu trúc folder gốc).
 * Hỗ trợ ZIP đa wrapper: kho-luu-tru/images/..., uploads/images/..., admincp/... (legacy).
 */
export function mapZipPathToStoragePath(
  zipPath: string,
  allZipPaths: string[],
): string {
  const normalized = zipPath.replace(/\\/g, '/');

  if (
    normalized.startsWith(IMAGE_STORAGE_PREFIX) ||
    normalized.startsWith(FILE_STORAGE_PREFIX) ||
    normalized.startsWith(VIDEO_STORAGE_PREFIX) ||
    normalized.startsWith(AUDIO_STORAGE_PREFIX)
  ) {
    return normalized;
  }

  const directStorage = sliceFromStorageRoot(normalized);
  if (directStorage) return directStorage;

  const directLegacy = legacyImagePath(normalized);
  if (directLegacy) return directLegacy;

  let peeled = peelKnownPrefixes(normalized);
  const peeledStorage = sliceFromStorageRoot(peeled) ?? legacyImagePath(peeled);
  if (peeledStorage) return peeledStorage;

  const roots = new Set(
    allZipPaths.map((entry) => entry.split('/')[0]).filter(Boolean),
  );
  if (roots.size === 1) {
    const root = [...roots][0];
    if (
      root &&
      root !== 'images' &&
      root !== 'files' &&
      root !== 'admincp' &&
      peeled.startsWith(`${root}/`)
    ) {
      const stripped = peeled.slice(root.length + 1);
      const strippedStorage =
        sliceFromStorageRoot(stripped) ?? legacyImagePath(stripped);
      if (strippedStorage) return strippedStorage;
      // Chỉ bỏ wrapper khi bên trong đã có images/ hoặc files/ (vd. kho-luu-tru/images/…).
      if (
        stripped.startsWith(IMAGE_STORAGE_PREFIX) ||
        stripped.startsWith(FILE_STORAGE_PREFIX) ||
        stripped.startsWith(VIDEO_STORAGE_PREFIX) ||
        stripped.startsWith(AUDIO_STORAGE_PREFIX)
      ) {
        peeled = stripped;
      }
    }
  }

  return peeled;
}

src/users/users.controller.ts.content:
import { toEntityId } from '../common/entity-id';
/**
 * Users Admin API Controller.
 * GET list, options, :id; POST (create); PUT :id; POST bulk; DELETE :id/hard-delete; DELETE :id; POST :id/restore.
 * Header: X-User-Id (bắt buộc). Không trả password.
 */
import {
  ApiTags,
  ApiOperation,
  ApiResponse,
  ApiBody,
  ApiQuery,
  ApiParam,
  ApiHeader,
} from '@nestjs/swagger';
import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Body,
  Param,
  Query,
  Headers,
  Res,
  Logger,
} from '@nestjs/common';
import type { Response } from 'express';
import { UsersService } from './users.service';
import { NotificationsService } from '../notifications/notifications.service';
import { NotificationKind } from '../entities/notification.entity';
import { SessionsService } from '../sessions/sessions.service';
import { SocketGateway } from '../socket/socket.gateway';
import {
  createSuccessResponse,
  createErrorResponse,
} from '../common/api-response';
import { APP_HEADERS, ADMIN_ROUTES } from '../config/constants';
import { Permissions } from '../common/permissions.decorator';
import { PERMISSIONS, RESOURCES, ACTIONS } from '../config/permissions';
import { parseAdminListLimit } from '../common/parse-list-query';

export class CreateUserDto {
  email: string;
  name: string;
  password: string;
  bio: string;
  avatar: string;
  phone: string;
  address: string;
  citizenId: string;
  isActive: boolean;
  roleIds: string[];
}

export class UpdateUserDto {
  email: string;
  name: string;
  password: string;
  bio: string;
  avatar: string;
  phone: string;
  address: string;
  citizenId: string;
  isActive: boolean;
  roleIds: string[];
}

export class BulkActionDto {
  action: 'delete' | 'restore' | 'hard-delete' | 'active' | 'unactive';
  ids: string[];
}

type BulkAction = 'delete' | 'restore' | 'hard-delete' | 'active' | 'unactive';

@ApiTags('Users')
@Permissions(PERMISSIONS.USERS_VIEW)
@Controller(ADMIN_ROUTES.USERS)
export class UsersController {
  private readonly logger = new Logger(UsersController.name);
  private readonly listStatuses = new Set(['active', 'deleted', 'all']);
  private readonly bulkActions = new Set<BulkAction>([
    'delete',
    'restore',
    'hard-delete',
    'active',
    'unactive',
  ]);

  constructor(
    private readonly usersService: UsersService,
    private readonly notificationsService: NotificationsService,
    private readonly sessionsService: SessionsService,
    private readonly socketGateway: SocketGateway,
  ) {}

  private logActivity(
    userId: string,
    title: string,
    description: string,
    actionUrl?: string,
    metadata?: Record<string, unknown>,
  ): void {
    void this.notificationsService
      .create({
        userId: toEntityId(userId),
        kind: NotificationKind.SYSTEM,
        title,
        description,
        actionUrl: actionUrl ?? null,
        metadata: metadata ?? undefined,
      })
      .catch(() => {});
  }

  private getUserId(
    headers: Record<string, string | undefined>,
  ): string | null {
    const id = headers[APP_HEADERS.USER_ID]?.trim();
    return id || null;
  }

  private unauthorized(
    res: Response,
    headerName: string = APP_HEADERS.USER_ID,
  ): Response {
    const { statusCode, body } = createErrorResponse(
      `Thiếu header ${headerName}`,
      {
        status: 401,
      },
    );
    return res.status(statusCode).json(body);
  }

  private parseListStatus(input?: string): 'active' | 'deleted' | 'all' {
    if (input && this.listStatuses.has(input)) {
      return input as 'active' | 'deleted' | 'all';
    }
    return 'active';
  }

  private isBulkAction(value: string): value is BulkAction {
    return this.bulkActions.has(value as BulkAction);
  }

  /** Thu hồi mọi phiên của user và emit session:revoked(reason: account_locked). */
  private async revokeSessionsAndEmitAccountLocked(
    targetUserId: string,
  ): Promise<void> {
    const { sessionIds } =
      await this.sessionsService.revokeAllSessionsByUserId(targetUserId);
    for (const sessionId of sessionIds) {
      this.socketGateway.emitSessionRevoked(
        String(sessionId),
        'account_locked',
      );
    }
  }

  @Get()
  @ApiOperation({ summary: 'List users with pagination' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  @ApiQuery({ name: 'page', required: false, type: Number })
  @ApiQuery({ name: 'limit', required: false, type: Number })
  @ApiQuery({ name: 'search', required: false, type: String })
  @ApiQuery({
    name: 'status',
    required: false,
    enum: ['active', 'deleted', 'all'],
  })
  @ApiResponse({ status: 200, description: 'Users retrieved successfully' })
  @ApiResponse({ status: 401, description: 'Missing X-User-Id header' })
  async list(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Query('page') page?: string,
    @Query('limit') limit?: string,
    @Query('search') search?: string,
    @Query('status') status?: string,
    @Query() query?: Record<string, string>,
  ) {
    this.logger.log(
      `list page=${page ?? 1} limit=${limit ?? 10} status=${status ?? 'active'}`,
    );
    const userId = this.getUserId(headers);
    if (!userId) {
      this.logger.warn(`list: Missing ${APP_HEADERS.USER_ID}`);
      return this.unauthorized(res);
    }
    const filters: Record<string, string> = {};
    if (query) {
      for (const [key, value] of Object.entries(query)) {
        const m = key.match(/^filter\[(.+)\]$/);
        if (!m) continue;
        const raw = value;
        const single = Array.isArray(raw)
          ? raw.length
            ? String(raw[0])
            : ''
          : raw != null
            ? String(raw)
            : '';
        if (single) filters[m[1]] = single;
      }
    }
    const result = await this.usersService.list({
      page: Math.max(1, parseInt(String(page), 10) || 1),
      limit: parseAdminListLimit(limit, 10),
      search: search?.trim(),
      status: this.parseListStatus(status),
      filters: Object.keys(filters).length ? filters : undefined,
    });
    const { statusCode, body } = createSuccessResponse({
      data: result.data,
      pagination: result.pagination,
    });
    return res.status(statusCode).json(body);
  }

  @Get('options')
  @ApiOperation({ summary: 'Get user options for dropdowns' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  @ApiQuery({ name: 'column', required: false, type: String })
  @ApiQuery({ name: 'search', required: false, type: String })
  @ApiQuery({ name: 'limit', required: false, type: Number })
  @ApiResponse({ status: 200, description: 'Options retrieved successfully' })
  async options(
